function records(){const all=[...owner.records.filter(r=>r.completedAt),...state.localRecords];return [...new Map(all.map(r=>[r.id,r])).values()].sort((a,b)=>b.completedAt-a.completedAt);}
const DRIFT_AXES=[['lead','主導欲'],['yield','委譲欲'],['sadism','加虐・翻弄'],['masochism','被虐・被翻弄'],['restraintReceive','被拘束'],['receiveCare','甘え・庇護']];
function historyPane(){
  const d=state.draft,rows=records(),current={id:d.id,profile:localProfile(),context:d.context,completedAt:d.completedAt};
  let {before,items}=historyComparison(current,rows,DRIFT_AXES);
  if(!before){
    const cross=rows.filter(r=>r.id!==current.id&&r.profile?.facets&&r.completedAt<current.completedAt).sort((a,b)=>b.completedAt-a.completedAt)[0];
    if(cross){before=cross;items=DRIFT_AXES.map(([id,label])=>({id,label,now:facetRate(current.profile?.facets?.find(f=>f.id===id)),before:facetRate(cross.profile?.facets?.find(f=>f.id===id))}));}
  }
  const date=r=>new Date(r.completedAt).toLocaleDateString('ja-JP',{month:'short',day:'numeric'});
  const frameLabel=r=>r?.context?.timeframe==='now'?'今の望み(now)':'普段の好み(recent)';
  const biggest=items.filter(f=>f.now!==null&&f.before!==null).sort((a,b)=>Math.abs(b.now-b.before)-Math.abs(a.now-a.before))[0];
  const driftNote=before&&biggest&&biggest.now!==biggest.before?`前回の「${frameLabel(before)}」から今回の「${frameLabel(current)}」で、最も揺らいだのは【${biggest.label}（${biggest.now>biggest.before?`Δ+${biggest.now-biggest.before}%`:`Δ${biggest.now-biggest.before}%`}）】です。`:'普段の自分（recent）と今夜の気分（now）でどう性癖が揺らいだかを比較しています。';
  const drift=before?`<div class="drift-box"><div class="drift-head"><strong>前の記録との時間軸（Temporal Drift）比較</strong><span>${date(before)} → ${date(current)}</span></div><p class="temporal-note">${esc(driftNote)}</p>${items.map(f=>{const diff=f.now!==null&&f.before!==null?f.now-f.before:null;const delta=diff===null?'未回答':diff>0?`Δ+${diff}%`:diff<0?`Δ${diff}%`:'±0%';return `<div class="drift-row"><span class="drift-label">${esc(f.label)}</span><div class="drift-bars">${f.before!==null?`<i class="drift-prev" style="width:${f.before}%"></i>`:''}${f.now!==null?`<i class="drift-cur" style="width:${f.now}%"></i>`:''}</div><span class="drift-val">${delta}</span></div>`;}).join('')}<p class="hint">真鍮色が前回、深紅が今回。気分や相手で揺らぐ差分（Δ+%）を可視化しています。</p></div>`:'<p class="history-empty">別の日や「今の望み」でもう一度答えると、普段の自分（recent）と今夜の気分（now）でどう性癖が揺らいだか（Δ+%）を比べられます。</p>';
  return `<h2>${text('その日の、好きが残る。')}</h2><p class="record-state">${d.consent?(d.synced?'このカルテを記録しました。':'回答はこの端末に保存済みです。接続でき次第、記録します。'):'この端末だけに保存しています。'}</p>${d.syncError?`<p class="error">${esc(d.syncError)}</p>${btn('もう一度、記録する','retry-sync','text-button')}`:''}${drift}<div class="timeline">${rows.slice(0,before?2:3).map(r=>`<button data-record="${esc(r.id)}"><time>${date(r)}</time><div><strong>${esc(r.profile.title)}</strong><span>${r.context?.timeframe==='now'?'今の望み':'普段の好み'} · ${esc(MOODS[r.context?.mood]||'気分は未回答')}</span></div></button>`).join('')}</div><div class="record-actions">${!d.consent?btn('この結果を記録する','record-for-history','primary'):''}${btn('今の望みで、もう一度答える','start-now',d.consent?'primary':'secondary')}${rows.length>3?btn('すべての記録を見る','history-all','text-button'):''}${d.consent?btn(owner.hasRecovery?'自分の記録・ログイン':'記録を引き継げるようにする','account','text-button'):''}</div>`;
}
function recordCurrent(next='profile'){recordNext=next;recordShareOptions=next==='share'?{tags:[...shareCard.tags],includeNote:!!$('#include-note')?.checked}:null;modal('この結果を、記録する。',`<p>今選んだ回答を、そのまま履歴に残します。答え直す必要はありません。</p><label class="check"><input type="checkbox" id="record-consent" checked><span>診断の改善と自分の履歴のために、回答と利用の記録を提供します。</span></label><p class="hint">回答一覧は公開しません。広告への利用は、別に選べます。<a href="/privacy/" target="_blank" rel="noopener">詳しく見る</a></p>${btn('同意して、この結果を記録する','confirm-record','primary wide')}${btn('戻る','close','text-button wide')}<p id="record-error" class="error" role="alert"></p>`);}
