function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function compareModal(){modal('二人のカルテを、比べる。',`<label class="field">相手の共有リンク<input id="partner-link" type="url" value="${esc(state.partnerLink||'')}" placeholder="https://…/s/…" maxlength="4500"></label>${btn('この結果と比べる','run-compare','primary wide')}<div id="comparison-output"></div><p id="compare-error" class="error" role="alert"></p>`);}
async function readPartner(value){const url=new URL(value);if([location.origin,'https://nocturne.ai-yu-me.com','https://heki16-pro.aiyume.workers.dev','https://nocturne.aiyume.workers.dev'].includes(url.origin)&&/^\/s\/[A-Za-z0-9_-]{16}$/.test(url.pathname))return (await api('/api/share/'+url.pathname.split('/').pop())).card;const old=readResultLink(value);return {title:old.title,quote:old.signature||old.gap?.shareText||old.description,summary:old.description,tags:old.tags?.map(t=>t.label)||[],traits:old.dims?.filter(d=>d.score>=65).map(d=>({narrative:'story',aesthetic:'style',pamper:'receiveCare',wet:'wet',cool:'space',lead:'lead',yield:'yield',sadism:'sadism',masochism:'masochism'})[d.id]).filter(Boolean)||[]};}
function compareMarkup(a,b){
  const items=compare(a,b);
  return `<div class="compare-names"><strong>${esc(a.title)}</strong><span>×</span><strong>${esc(b.title)}</strong></div>${items.map(l=>`<section class="comparison-line"><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></section>`).join('')}<p class="hint">お互いが共有した好みから、話のきっかけを探せます。その日の希望は、本人に確かめてください。</p>`;
}
function find(){if(state.draft?.complete&&!state.draft.synced||!owner.signedIn||!owner.records.some(r=>r.completedAt&&r.profile?.answered>=12)){measure('listing_gate');const p=localProfile(),recordable=p&&(!state.draft.consent||!state.draft.serverStarted),limited=owner.signedIn&&p&&!recordable;return `<section class="deck empty"><span class="editorial-label">RESONANCE</span><h1>${text("匿名のカルテを探す。")}</h1><p>${recordable?'今の結果を記録すると、匿名のカルテを探せます。答え直す必要はありません。':limited?'半分以上の場面に答えると、好みの合うカルテを探せます。':'診断を終え、回答を記録すると、匿名の募集一覧を開けます。自分の掲載は、別に選べます。'}</p>${btn(recordable?'この結果を記録して探す':limited?'もう一度、好きな場面を選ぶ':p?'記録を引き継いで探す':'自分の性癖を診断する',recordable?'record-for-find':p&&!limited?'account':'start','primary')}${!p?btn('記録を引き継ぐ','account','text-button'):''}</section>`;}measure('listing_open');const item=listingItems[candidateIndex];return `<section class="deck discovery"><div class="discovery-head"><div><span class="editorial-label">RESONANCE</span><h1>${text("匿名のカルテを探す。")}</h1></div>${btn('絞り込む','filters','secondary')}</div><p class="hint">掲載した言葉だけで、好みを比べます。</p>${item?`<div class="candidate"><div class="candidate-top"><span class="anonymous">匿名 · ${esc(item.id.slice(-4))}${item.age!=='unset'?' · '+esc(AGES[item.age]):''}${item.gender!=='unset'?' · '+esc(GENDERS[item.gender]):''}</span>${btn(icon('more'),'candidate-menu','plain','aria-label="相手のカルテのメニュー"')}</div><h2>${text(item.card.title)}</h2><blockquote>${text(item.card.quote)}</blockquote><div class="tags">${item.card.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p>${esc({similar:'似ている好みを知りたい',complement:'役の合う好みを知りたい',any:'いろいろな好みを知りたい'}[item.intent])}</p>${btn(item.interested?'気になるを取り消す':'気になる','interest',item.interested?'secondary':'primary')}</div><div class="candidate-pager">${btn(icon('back')+'前の候補','prev-candidate','plain',candidateIndex===0?'disabled':'')}<span>${candidateIndex+1} / ${listingItems.length}</span>${btn('次の候補'+icon('arrow'),'next-candidate','plain',candidateIndex>=listingItems.length-1&&!listingNext?'disabled':'')}</div>`:`<div class="candidate empty"><h2>${listingError?'カルテを読み込めませんでした。':loadedListing?'今は、条件に合うカルテがありません。':'カルテを探しています。'}</h2><p>${listingError?esc(listingError):loadedListing?'条件を変えるか、日を改めてのぞいてみてください。':'少しお待ちください。'}</p>${btn('もう一度、探す','load-listings','secondary')}</div>`}<div class="discovery-bottom">${btn(owner.listing?'自分の掲載を管理する':'自分のカルテを掲載する','publish-modal','secondary')}${owner.mutual?.length?btn(`お互いに気になる · ${owner.mutual.length}件`,'mutual','text-button'):''}</div></section>`;}
async function loadListings(more=false){loadedListing=false;listingError='';render();try{const p=await api('/api/listings?'+new URLSearchParams({...filters,...(more&&listingNext?{before:listingNext}:{})}));candidateIndex=more?listingItems.length:0;listingItems=more?[...listingItems,...p.items]:p.items;listingNext=p.next;loadedListing=true;render();}catch(e){loadedListing=true;listingError=e.message;render();}}
function publishModal(interestId=''){const selected=owner.records.find(r=>r.id===state.draft?.id&&r.completedAt&&r.profile?.answered>=12)||owner.records.find(r=>r.completedAt&&r.profile?.answered>=12);if(!selected)return;const card=listingCard(selected.profile);modal(interestId?'気になるを届ける':owner.listing?'掲載を管理する':'匿名で掲載する',`${interestId?'<p>先に、自分のカルテも掲載します。</p>':''}<div class="publication-preview"><strong>${text(card.title)}</strong><blockquote>${text(card.quote)}</blockquote><div class="tags">${card.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><p class="hint">診断を終えた人に、この内容を見せます。</p><details><summary>目的・公開する属性（任意）</summary><label class="field">知りたい相手 ${select('listing-intent',{any:'いろいろな好み',similar:'似ている好み',complement:'役の合う好み'},owner.listing?.intent||'any')}</label><div class="field-pair"><label class="field">公開する年代 ${select('publish-age',{...AGES,unset:'表示しない'},owner.listing?.age||'unset')}</label><label class="field">公開する性別 ${select('publish-gender',{...GENDERS,unset:'表示しない'},owner.listing?.gender||'unset')}</label></div></details><p class="hint">7日間掲載。いつでも取り消せます。回答・履歴・自由タグ・連絡先は公開しません。${owner.listing?'更新すると、これまでの気になるは取り消されます。':''}メッセージは送れません。</p>${btn(interestId?'掲載して、気になるを送る':owner.listing?'このカルテで掲載し直す':'同意して掲載する','publish','primary wide',`data-record-id="${esc(selected.id)}" data-interest-id="${esc(interestId)}"`)}${owner.listing?btn('掲載を取り消す','unpublish','text-button wide'):''}<p id="publish-error" class="error" role="alert"></p>`);}

async function publishSelection(target){
  const recordId=target.dataset.recordId,interestId=target.dataset.interestId,record=owner.records.find(r=>r.id===recordId),age=$('#publish-age').value,gender=$('#publish-gender').value,persona={age:age==='unset'?record.persona.age:age,gender:gender==='unset'?record.persona.gender:gender};
  if(persona.age!==record.persona.age||persona.gender!==record.persona.gender){await api('/api/persona',{id:recordId,persona});if(state.draft?.id===recordId){state.draft.persona=persona;save();}}
  await api('/api/listing',{publish:true,recordId,intent:$('#listing-intent').value,showAge:age!=='unset',showGender:gender!=='unset'});measure('listing_publish');
  let outcome=null;if(interestId)try{outcome=await api('/api/interest',{id:interestId,interested:true});if(outcome.interested)measure('interest');}catch{outcome={uncertain:true};}
  await refreshOwner();close();await loadListings();
  const mutual=owner.mutual?.find(m=>m.id===interestId);
  if(outcome?.mutual&&mutual&&owner.listing)modal('お互いに、気になる。',compareMarkup(owner.listing.card,mutual.card));
  else if(outcome?.uncertain)say('掲載しました。気になるを届けたかは、表示を確認してください。');
  else say(interestId?'掲載して、気になるを届けました。':'7日間、匿名で掲載しました。');
}
function showRecord(id){const r=records().find(r=>r.id===id);if(!r)return;modal('その日に答えた、自分。',`<p>${new Date(r.completedAt).toLocaleString('ja-JP')}</p><h2>${esc(r.profile.title)}</h2><p>${esc(r.profile.quote)}</p><p>${esc(r.profile.summary)}</p>${owner.records.some(r=>r.id===id)?btn('この記録を削除する','delete-record-prompt','text-button',`data-id="${esc(id)}"`):''}`);}
function render(){accrue();const route=location.hash.slice(1)||'home';$('#main').innerHTML=route==='quiz'?quiz():route==='profile'?result():route==='find'?find():home();if($('#result-preview'))drawCard(shared||publicCard(activeProfile()),$('#result-preview'));document.body.dataset.view=route;document.querySelectorAll('[data-route]').forEach(a=>a.setAttribute('aria-current',a.dataset.route===route?'page':'false'));($('#question-title')||$('.result-pane')||$('#main')).focus({preventScroll:true});}

document.addEventListener('change',e=>{
  if(e.target.name==='gender-pill'&&$('#gender'))$('#gender').value=e.target.value;
  if((['mood','age','gender'].includes(e.target.id)||e.target.name==='gender-pill')&&$('#start-error'))$('#start-error').textContent='';
  if(e.target.name==='timeframe')$('#timeframe-hint').textContent=e.target.value==='now'?'今この瞬間にしたい・されたい方で答える':'日頃よく惹かれる傾向で答える';
  if(e.target.name==='answer'){$('[data-action=none]').setAttribute('aria-pressed','false');const d=state.draft,q=SCENES[d.index],old=d.answers[q.id]||0,bit=1<<Number(e.target.value);let mask=q.single?bit:e.target.checked?old|bit:old&~bit;if(q.boundary&&e.target.value==='4'&&e.target.checked)mask=16;else if(q.boundary&&e.target.checked)mask&=15;if(bits(mask).length>(q.boundary?4:2)){e.target.checked=false;$('#selection-error').textContent='2つまで選べます。別のものを選ぶなら、先に一つ外してください。';return;}d.answers[q.id]=mask||null;d.revision++;d.synced=false;save();document.querySelectorAll('.choice').forEach(label=>{const input=label.querySelector('input');input.checked=!!(mask&(1<<Number(input.value)));label.classList.toggle('selected',input.checked);});$('#selection-error').textContent=mask?(q.single?'選択済み':bits(mask).length+'つ選択中'):'';$('[data-action=next]').disabled=!mask;}
  if(e.target.name==='share-tag'||e.target.id==='include-note'){if(document.querySelectorAll('[name=share-tag]:checked').length>3){e.target.checked=false;say('共有するタグは、3つまで選べます。');return;}updateShare();}
});
document.addEventListener('submit',e=>{if(e.target.id==='tag-form'){e.preventDefault();const label=normalizeLabel($('#tag-input').value).slice(0,24);if(!label)return;if(state.tags.length>=24){say('タグは24個まで保存できます。');return;}state.tags=organizeTags([...state.tags,{label,kind:'like'}]);save();editTags();}});
document.addEventListener('click',async e=>{
 if(e.target.closest('#share-x')&&!sample&&!shared)measure('x_open');
 const navigation=e.target.closest('[data-route]');
 if(navigation&&(shared||sample)){e.preventDefault();if(shared){state.partnerLink=location.href;save();}shared=null;sample=false;page=0;subpage=0;history.replaceState(null,'','/#'+navigation.dataset.route);render();if(navigation.dataset.route==='find'&&owner.signedIn)void loadListings();return;}
 const target=e.target.closest('[data-action]'),action=target?.dataset.action;
 if(e.target.closest('[aria-disabled=true]')){e.preventDefault();return;}
 const tab=e.target.closest('[data-page]');if(tab){page=Number(tab.dataset.page);subpage=0;render();return;}
 const sub=e.target.closest('[data-subpage]');if(sub){subpage=Number(sub.dataset.subpage);render();return;}
 const recordButton=e.target.closest('[data-record]');if(recordButton){showRecord(recordButton.dataset.record);return;}
 const remove=e.target.closest('[data-remove-tag]');if(remove){state.tags.splice(Number(remove.dataset.removeTag),1);save();editTags();return;}
 const mutual=e.target.closest('[data-mutual]');if(mutual){try{await refreshOwner(false,true);}catch(error){say(error.message);return;}const other=owner.mutual.find(m=>m.id===mutual.dataset.mutual);if(!other){close();say('今は、このカルテを比べられません。');return;}if(owner.listing)modal('二人のカルテを、比べる。',compareMarkup(owner.listing.card,other.card));return;}
 if(!action)return;const busy=target.tagName==='BUTTON';if(busy)target.disabled=true;
 try{switch(action){
  case 'start':start('recent');break;case 'start-now':start('now');break;case 'confirm-start':confirmStart();break;
   case 'copy-link':await copy(shareUrl);break;case 'copy-post':await copy(postText());break;
  case 'sample':sample=true;shared=null;page=0;subpage=0;navigate('profile');render();break;
  case 'resume':sample=false;shared=null;navigate('quiz');render();break;
  case 'next':advance();break;case 'skip':advance(true);break;case 'none':{const d=state.draft;d.answers[d.index]=0;d.revision++;d.synced=false;save();document.querySelectorAll('.choice').forEach(el=>{el.classList.remove('selected');el.querySelector('input').checked=false;});target.setAttribute('aria-pressed','true');$('#selection-error').textContent='今回は当てはまらない';$('[data-action=next]').disabled=false;break;}
  case 'previous':accrue();state.draft.index=Math.max(0,state.draft.index-1);state.draft.revision++;save();render();break;
  case 'pause':accrue();void syncDraft();navigate('home');break;
  case 'next-page':page=Math.min(4,page+1);subpage=0;render();break;case 'prev-page':page=Math.max(0,page-1);subpage=0;render();break;
  case 'next-subpage':subpage=(subpage+1)%3;render();break;case 'go-manual':page=2;subpage=0;render();break;
  case 'toggle-censor':censorManual=!censorManual;render();document.querySelectorAll('.censor-toggle').forEach(b=>{b.classList.toggle('active',censorManual);b.setAttribute('aria-pressed',String(censorManual));});if($('#share-canvas'))updateShare();if($('#share-x'))$('#share-x').href='https://twitter.com/intent/tweet?'+new URLSearchParams({text:postText()});break;
  case 'open-share':openShare();break;case 'make-link':await makeLink();break;
  case 'save-image':$('#share-canvas').toBlob(blob=>download(blob,'nocturne-result.png'),'image/png');break;
  case 'account':accountModal();break;
  case 'all-evidence':{const p=activeProfile();modal('名前がついた、場面。',p.evidence.map(raw=>{const e=evidenceDisplay(raw);return `<section class="evidence-detail"><h3>${text(e.question)}</h3><p>${text(e.answers.join('／'))}</p></section>`;}).join(''));break;}
  case 'all-facets':{const p=activeProfile();modal('好きの輪郭を、もう少し。',`<div class="facet-list full-facets">${facetRows(orderedFacets(p))}</div><p class="hint">選ばなかった内容を、苦手だと決めつけるものではありません。</p>`);break;}
  case 'record-for-share':recordCurrent('share');break;case 'record-for-find':recordCurrent('find');break;case 'record-for-history':recordCurrent('profile');break;
  case 'confirm-record':await contributeCurrent();break;
  case 'blocked-list':{const p=await api('/api/blocks');modal('非表示を、取り消す。',p.items.length?`<label class="field">非表示にしたカルテ ${select('blocked-choice',Object.fromEntries(p.items.map(i=>[i.id,i.title])),p.items[0].id)}</label>${btn('このカルテを再表示する','unblock','secondary wide')}`:'<p>非表示にしているカルテはありません。</p>');break;}
  case 'unblock':await api('/api/unblock',{id:$('#blocked-choice').value});close();await loadListings();say('非表示を取り消しました。');break;
  case 'history-all':modal('記録を、選ぶ。',`<label class="field">答えた日 ${select('history-choice',Object.fromEntries(records().map(r=>[r.id,new Date(r.completedAt).toLocaleDateString('ja-JP')+' · '+r.profile.title])),records()[0]?.id)}</label>${btn('この日の記録を開く','open-history','primary wide')}`);break;
  case 'open-history':showRecord($('#history-choice').value);break;
  case 'make-recovery':{const p=await api('/api/recovery/create',{});owner.hasRecovery=true;$('#recovery-output').innerHTML=`<label class="field">今回だけ表示するキー<input readonly id="created-recovery" value="${esc(p.key)}" autocomplete="off"></label><p class="hint">安全な場所に保存してください。閉じると、ここからは再表示できません。</p>${btn('キーをコピー','copy-recovery','secondary wide')}`;target.hidden=true;break;}
  case 'copy-recovery':await copy($('#created-recovery').value);break;
  case 'login':epoch++;syncController?.abort();syncing=false;syncAgain=false;tokenPromise=null;await api('/api/recovery/login',{key:$('#recovery-key').value.trim(),token:await botToken()});await refreshOwner(true);close();sample=false;shared=null;page=3;navigate('profile');render();say('記録を引き継ぎました。');break;
  case 'retry-sync':await syncDraft();render();break;
  case 'persona':modal('年代・性別を、変更する。',`<p>統計では、同じ年代や性別の回答をまとめます。募集一覧への表示は、掲載するときに別に選びます。</p><label class="field">年代 ${select('edit-age',PROFILE_OPTIONS.age,state.draft.persona.age)}</label><label class="field">性別 ${select('edit-gender',PROFILE_OPTIONS.gender,state.draft.persona.gender)}</label>${btn('この内容で保存する','save-persona','primary wide')}`);break;
  case 'save-persona':{const persona={age:$('#edit-age').value,gender:$('#edit-gender').value};if(state.draft.consent&&state.draft.serverStarted)await api('/api/persona',{id:state.draft.id,persona});state.draft.persona=persona;save();close();say('保存しました。');break;}
  case 'edit-tags':editTags();break;case 'save-note':state.note=$('#personal-note').value.trim();save();close();say('自分の言葉を保存しました。');break;
  case 'backup':download(new Blob([JSON.stringify({version:1,state,records:owner.records},null,2)],{type:'application/json'}),'nocturne-private-records.json');break;
  case 'logout-prompt':modal('この端末から、ログアウトしますか？',`<p>この端末の回答とタグを消し、記録を閉じます。保存先の履歴は残ります。引き継ぎキーを保存してから進んでください。</p>${btn('ログアウトして端末の回答を消す','logout','secondary wide')}${btn('戻る','close','text-button wide')}`);break;
  case 'logout':await api('/api/logout',{});clearLocal();close();navigate('home');render();say('ログアウトしました。');break;
  case 'delete-prompt':modal('提供した回答を、取り消しますか？',`<p>保存先の回答・履歴・掲載・共有リンクを削除します。この端末の回答も消します。保存した画像や、相手がコピーした内容は消せません。</p><label class="check"><input type="checkbox" id="delete-confirm"><span>取り消す内容を確認しました。</span></label>${btn('提供を取り消して、記録を削除する','delete-account','secondary wide')}${btn('戻る','close','text-button wide')}`);break;
  case 'delete-account':if(!$('#delete-confirm').checked){say('取り消す内容を確認してください。');break;}await api('/api/account/delete',{confirm:'delete-my-records'});clearLocal();close();navigate('home');render();say('提供した回答と記録を削除しました。');break;
  case 'delete-record-prompt':modal('この日の記録を、削除しますか？',`<p>この日の回答と履歴を削除します。掲載したカルテと共有リンクは別に残ります。すべて取り消す場合は、記録の管理画面から回答の提供を取り消してください。</p>${btn('この日の記録を削除する','delete-record','secondary wide',`data-id="${esc(target.dataset.id)}"`)}${btn('戻る','close','text-button wide')}`);break;
  case 'delete-record':{const id=target.dataset.id;await api('/api/record/delete',{id});state.localRecords=state.localRecords.filter(r=>r.id!==id);if(state.draft?.id===id)state.draft=null;save();await refreshOwner();close();render();say('この日の記録を削除しました。');break;}
  case 'compare-modal':compareModal();break;
  case 'run-compare':{const a=localProfile();if(!a){$('#compare-error').textContent='先に自分の診断をすると、比べられます。';break;}const partner=await readPartner($('#partner-link').value);$('#comparison-output').innerHTML=compareMarkup(publicCard(a),partner);break;}
  case 'find':sample=false;shared=null;await refreshOwner();navigate('find');break;
  case 'load-listings':await refreshOwner();await loadListings();break;
  case 'prev-candidate':candidateIndex=Math.max(0,candidateIndex-1);render();break;case 'next-candidate':if(candidateIndex===listingItems.length-1&&listingNext)await loadListings(true);else{candidateIndex=Math.min(listingItems.length-1,candidateIndex+1);render();}break;
  case 'filters':modal('気になるカルテを、絞り込む。',`<label class="field">好きの重なり ${select('filter-relation',{any:'指定しない',similar:'共通する好みがある',complement:'役の合う好みがある'},filters.relation)}</label><label class="field">相手の目的 ${select('filter-intent',{'':'指定しない',similar:'似ている好み',complement:'役の合う好み',any:'いろいろな好み'},filters.intent)}</label><label class="field">気になる好み ${select('filter-trait',{'':'指定しない',...Object.fromEntries(FACETS.map(f=>[f.id,f.label]))},filters.trait)}</label><label class="field">年代 ${select('filter-age',{'':'指定しない',...AGES},filters.age)}</label><label class="field">性別 ${select('filter-gender',{'':'指定しない',...GENDERS},filters.gender)}</label><p class="hint">相手が掲載を選んだ情報で探します。非公開の年代・性別からは探せません。</p>${btn('この条件で探す','apply-filters','primary wide')}`);break;
  case 'apply-filters':filters={relation:$('#filter-relation').value,trait:$('#filter-trait').value,intent:$('#filter-intent').value,age:$('#filter-age').value,gender:$('#filter-gender').value};close();await loadListings();break;
  case 'publish-modal':publishModal();break;
  case 'publish':await publishSelection(target);break;
  case 'unpublish':await api('/api/listing',{publish:false});await refreshOwner();close();await loadListings();say('掲載を取り消しました。');break;
  case 'interest':{const item=listingItems[candidateIndex];if(!owner.listing){publishModal(item.id);break;}const p=await api('/api/interest',{id:item.id,interested:!item.interested});item.interested=p.interested;if(p.interested)measure('interest');await refreshOwner();render();if(p.mutual)modal('お互いに、気になる。',compareMarkup(owner.listing.card,item.card));else say(p.interested?'気になるを届けました。':'気になるを取り消しました。');break;}
  case 'candidate-menu':modal('このカルテについて。',`${btn('このカルテを隠す','block','secondary wide')}${btn('通報する','report','text-button wide')}`);break;
  case 'block':{const item=listingItems[candidateIndex];await api('/api/block',{id:item.id});await refreshOwner();close();listingItems.splice(candidateIndex,1);candidateIndex=Math.max(0,Math.min(candidateIndex,listingItems.length-1));render();say('お互いに非表示にしました。記録の管理から戻せます。');break;}
  case 'report':modal('このカルテを、通報する。',`<label class="field">理由 ${select('report-reason',{unwanted:'不快に感じた',impersonation:'なりすましが疑われる',underage:'18歳未満の利用が疑われる',other:'その他'},'unwanted')}</label><p>通報した相手は、お互いの一覧から非表示になります。</p>${btn('通報して非表示にする','send-report','secondary wide')}`);break;
  case 'send-report':await api('/api/report',{id:listingItems[candidateIndex].id,reason:$('#report-reason').value});await refreshOwner();close();await loadListings();say('通報を受け付けました。');break;
  case 'mutual':await refreshOwner(false,true);render();modal('お互いに、気になるカルテ。',`${owner.mutual.map(m=>`<button class="mutual-item" data-mutual="${esc(m.id)}">${esc(m.card.title)}</button>`).join('')}<p class="hint">掲載の取り消しやブロックをすると、この一覧から消えます。</p>`);break;
  case 'open-promotion':if(!sample&&!shared&&state.draft?.complete)openPromotion({profile:localProfile(),recordId:state.draft.id,showModal:modal});break;
  case 'menu':modal('NOCTURNE',`<nav class="menu-links"><a href="/guide/" target="_blank" rel="noopener">楽しみ方</a><a href="/types/" target="_blank" rel="noopener">関係性図鑑</a><a href="/library/" target="_blank" rel="noopener">読みもの</a><a href="/privacy/" target="_blank" rel="noopener">プライバシー</a><a href="/advertising/" target="_blank" rel="noopener">広告について</a></nav>${btn('自分の記録・ログイン','account','text-button wide')}`);break;
  case 'close':close();break;
 }}catch(error){const field=$('#account-error')||$('#publish-error')||$('#compare-error')||$('#share-feedback');if(field)field.textContent=error.message;else say(error.message);}finally{if(busy&&target.isConnected)target.disabled=false;}
});
function clearLocal(){forgetPromotionConsent();clearVaults(localStorage);state={v:1,draft:null,localRecords:[],tags:[],note:''};owner={signedIn:false,records:[],mutual:[]};shared=null;sample=false;listingItems=[];save();}
window.addEventListener('hashchange',()=>{if(!['#profile','#quiz'].includes(location.hash)){sample=false;shared=null;}render();if(location.hash==='#find'&&owner.signedIn)void loadListings();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){accrue();void syncDraft();}else if(location.hash==='#quiz')entered=performance.now();});
window.addEventListener('online',()=>void syncDraft());
window.addEventListener('storage',e=>{if(e.key===KEY){const incoming=load();if(incoming.scope!==state.scope){state=incoming;void refreshOwner(true).then(()=>render());}}});
async function init(){await prepareState();try{config=await api('/api/config');}catch{}await refreshOwner();const short=/^\/s\/[A-Za-z0-9_-]{16}$/.test(location.pathname),legacy=location.hash.startsWith('#share=');if(short||legacy){try{const meta=document.querySelector('meta[name=nocturne-card]');shared=short?(meta?JSON.parse(meta.content):(await api('/api/share/'+location.pathname.split('/').pop())).card):await readPartner(location.href);page=0;sample=false;history.replaceState(null,'',location.pathname+'#profile');}catch{say('共有結果を読み取れませんでした。期限やリンクを確認してください。');}}render();if(state.draft?.consent&&!state.draft.synced)void syncDraft();if(location.hash==='#find'&&owner.signedIn)void loadListings();}
render();void init();

document.addEventListener('change',e=>{if(e.target.id==='share-name-only'){shareNameOnly=e.target.checked;updateShare();}});
